# Surah Ar-Ra'd (chapter 13) — part 3: ayat 21-30 (IDs 1728-1737)
SURAH = 13

ENTRIES = {
1728: (
"اور وہ لوگ جو اس کو جوڑتے ہیں جس کو جوڑنے کا اللہ نے حکم دیا ہے اور اپنے رب سے ڈرتے ہیں اور برے حساب سے خوف کھاتے ہیں",
"""۱۔ صلہ رحمی اور اللہ کا حکم ماننا — برے حساب کا ڈر ایمان کا وصف۔
۲۔ ’’وَالَّذِينَ يَصِلُونَ مَا أَمَرَ اللَّهُ بِهِ أَن يُوصَلَ وَيَخْشَوْنَ رَبَّهُمْ وَيَخَافُونَ سُوءَ الْحِسَابِ‘‘ — اور وہ لوگ جو اس کو جوڑتے ہیں جس کو جوڑنے کا اللہ نے حکم دیا ہے اور اپنے رب سے ڈرتے ہیں اور برے حساب سے خوف کھاتے ہیں — یعنی یہ وہ لوگ ہیں جو اس رشتہ کو قائم رکھتے ہیں جس کو قائم رکھنے کا اللہ نے حکم دیا ہے اور اپنے رب سے ڈرتے ہیں اور برے حساب کا خوف کھاتے ہیں۔
۳۔ عملی سبق: صلہ رحمی کو ترک نہ کریں؛ رشتہ داری زندہ رکھیں؛ حساب کی یاد دل قوی رکھتی ہے۔"""
),
1729: (
"اور وہ لوگ جنہوں نے صبر کیا صرف اپنے رب کی رضا کے لیے اور نماز قائم کی اور ہم نے جو انہیں دیا اس میں سے پوشیدہ اور ظاہر خرچ کیا اور برائی کو اچھائی سے دباتے ہیں — انہی کے لیے آخرت کا گھر ہے",
"""۱۔ صبر — نماز — انفاق اور برے کاموں کا اچھا جواب: آخرت کے گھر والوں کی صفات۔
۲۔ ’’وَالَّذِينَ صَبَرُوا ابْتِغَاءَ وَجْهِ رَبِّهِمْ وَأَقَامُوا الصَّلَاۃَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَۃً وَيَدْرَءُونَ بِالْحَسَنَۃِ السَّيِّئَۃَ أُولَٰئِكَ لَهُمْ عُقْبَى الدَّارِ‘‘ — اور وہ لوگ جنہوں نے صبر کیا صرف اپنے رب کی رضا کے لیے اور نماز قائم کی اور ہم نے جو انہیں دیا اس میں سے پوشیدہ اور ظاہر خرچ کیا اور برائی کو اچھائی سے دباتے ہیں — انہی کے لیے آخرت کا گھر ہے — یعنی یہ وہ لوگ ہیں جنہوں نے صبر کیا صرف اپنے رب کی رضا کے لیے اور نماز قائم کی اور ہم نے جو انہیں دیا اس میں سے پوشیدہ اور ظاہر خرچ کیا اور برائی کو اچھائی سے دباتے ہیں — انہی کے لیے آخرت کا گھر ہے۔
۳۔ عملی سبق: تنگی میں بھی صبر کریں؛ پوشیدہ صدقہ دیں؛ برائی کا جواب اچھائی سے دیں۔"""
),
1730: (
"ہمیشگی کے باغات جن میں وہ داخل ہوں گے اور ان کے آباء اور ازواج اور اولاد میں سے جو نیک تھے — اور فرشتے ان پر ہر دروازے سے داخل ہوں گے",
"""۱۔ جنت دائمی — خاندان کا صالح ساتھ دے گا — فرشتے ہر دروازے سے سلام کرنے آتے ہیں۔
۲۔ ’’جَنَّاتُ عَدْنٍ يَدْخُلُونَهَا وَمَنْ صَلَحَ مِنْ آبَائِهِمْ وَأَزْوَاجِهِمْ وَذُرِّيَّاتِهِمْ وَالْمَلَائِكَۃُ يَدْخُلُونَ عَلَيْهِم مِّن كُلِّ بَابٍ‘‘ — ہمیشگی کے باغات جن میں وہ داخل ہوں گے اور ان کے آباء اور ازواج اور اولاد میں سے جو نیک تھے — اور فرشتے ان پر ہر دروازے سے داخل ہوں گے — یعنی جنت میں داخلوں کے لیے ہمیشگی کے باغات ہیں — جن میں وہ داخل ہوں گے اور ان کے آباء اور ازواج اور اولاد میں سے جو نیک تھے — اور فرشتے ان کے پاس ہر دروازے سے داخل ہوں گے۔
۳۔ عملی سبق: اپنے لیے — اپنے خاندان کے لیے جنت کی دعا کریں؛ نیکیوں کی اپنی نسل تک مالی مدد کریں۔"""
),
1731: (
"تم پر سلامتی ہو تمہارے صبر کی وجہ سے — پس آخرت کا گھر کیا خوب ہے",
"""۱۔ فرشتوں کی دائمی سلام — صبر کا صلہ جنت — بہترین انجام۔
۲۔ ’’سَلَامٌ عَلَيْكُم بِمَا صَبَرْتُمْ فَنِعْمَ عُقْبَى الدَّارِ‘‘ — تم پر سلامتی ہو تمہارے صبر کی وجہ سے — پس آخرت کا گھر کیا خوب ہے — یعنی تم پر سلامتی ہو تمہارے صبر کی وجہ سے — پس آخرت کا گھر کیا خوب ہے۔
۳۔ عملی سبق: صبر کا اصل بدلہ آخرت ہے؛ دنیا کی تلخیوں میں صبر کی راہ چنیں۔"""
),
1732: (
"اور وہ لوگ جو اللہ کا عہد توڑتے ہیں اس کی مضبوطی کے بعد اور جس کو جوڑنے کا اللہ نے حکم دیا ہے اسے کاٹتے ہیں اور زمین میں فساد کرتے ہیں — ان پر لعنت ہے اور ان کے لیے برا ٹھکانہ ہے",
"""۱۔ عہد توڑنا — قطع رحمی — فساد: لعنت اور برا گھر کا وعدہ۔
۲۔ ’’وَالَّذِينَ يَنقُضُونَ عَهْدَ اللَّهِ مِن بَعْدِ مِيثَاقِهِ وَيَقْطَعُونَ مَا أَمَرَ اللَّهُ بِهِ أَن يُوصَلَ وَيُفْسِدُونَ فِي الْأَرْضِ أُولَٰئِكَ لَهُمُ اللَّعْنَۃُ وَلَهُمْ سُوءُ الدَّارِ‘‘ — اور وہ لوگ جو اللہ کا عہد توڑتے ہیں اس کی مضبوطی کے بعد اور جس کو جوڑنے کا اللہ نے حکم دیا ہے اسے کاٹتے ہیں اور زمین میں فساد کرتے ہیں — ان پر لعنت ہے اور ان کے لیے برا ٹھکانہ ہے — یعنی یہ وہ لوگ ہیں جو اللہ کا عہد توڑتے ہیں اس کی مضبوطی کے بعد اور جس کو جوڑنے کا اللہ نے حکم دیا ہے اسے کاٹتے ہیں اور زمین میں فساد کرتے ہیں — انہی پر لعنت ہے اور ان کے لیے برا گھر ہے۔
۳۔ عملی سبق: عہد کی پاسداری — معاشرتی امن کی بنیاد ہے؛ فساد کرنے والوں سے الگ رہیں۔"""
),
1733: (
"اللہ جس کے لیے چاہتا ہے رزق کشادہ کرتا ہے اور جس کے لیے چاہتا ہے تنگ کرتا ہے — اور وہ دنیا کی زندگی میں خوش ہوتے ہیں — اور دنیا کی زندگی آخرت کے مقابلے میں صرف ایک سامان ہے",
"""۱۔ رزق اللہ کے ہاتھ میں؛ دنیا کی مسرت عارضی؛ آخرت کا مال دائمی۔
۲۔ ’’اللَّهُ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ وَفَرِحُوا بِالْحَيَاۃِ الدُّنْيَا وَمَا الْحَيَاۃُ الدُّنْيَا فِي الْآخِرَۃِ إِلَّا مَتَاعٌ‘‘ — اللہ جس کے لیے چاہتا ہے رزق کشادہ کرتا ہے اور جس کے لیے چاہتا ہے تنگ کرتا ہے — اور وہ دنیا کی زندگی میں خوش ہوتے ہیں — اور دنیا کی زندگی آخرت کے مقابلے میں صرف ایک سامان ہے — یعنی اللہ جس کے لیے چاہتا ہے رزق کشادہ کرتا ہے اور جس کے لیے چاہتا ہے تنگ کرتا ہے — اور یہ لوگ دنیا کی زندگی میں خوش ہو جاتے ہیں — اور دنیا کی زندگی آخرت کے مقابلے میں صرف ایک سامان ہے۔
۳۔ عملی سبق: امیری یا غریبی پر فخر و غم نہ کریں؛ آخرت کی تیاری اصل سرمایہ ہے۔"""
),
1734: (
"اور کافر کہتے ہیں اس پر اس کے رب کی طرف سے کوئی نشانی کیوں نہیں نازل کی گئی — کہیے بے شک اللہ جسے چاہے گمراہ کرتا ہے اور جو اس کی طرف رجوع کرے اسے ہدایت دیتا ہے",
"""۱۔ نشانی مانگنے والے کفار کو بتایا گیا کہ ہدایت اللہ کا اختیار ہے۔
۲۔ ’’وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَۃٌ مِّن رَّبِّهِ قُلْ إِنَّ اللَّهَ يُضِلُّ مَن يَشَاءُ وَيَهْدِي إِلَيْهِ مَنْ أَنَابَ‘‘ — اور کافر کہتے ہیں اس پر اس کے رب کی طرف سے کوئی نشانی کیوں نہیں نازل کی گئی — کہیے بے شک اللہ جسے چاہے گمراہ کرتا ہے اور جو اس کی طرف رجوع کرے اسے ہدایت دیتا ہے — یعنی کافر کہتے ہیں — اس پر اس کے رب کی طرف سے کوئی معجزہ یا نشانی کیوں نہیں نازل کی گئی — کہیے بے شک اللہ جسے چاہے گمراہ کرتا ہے اور جو اس کی طرف رجوع کرے اسے ہدایت دیتا ہے۔
۳۔ عملی سبق: ہدایت کی اصل قبولیت دل میں ہے؛ اللہ سے ہدایت مانگتے رہیں۔"""
),
1735: (
"وہ لوگ جو ایمان لائے اور جن کے دل اللہ کے ذکر سے سکون پاتے ہیں — خبردار! اللہ کے ذکر سے ہی دل سکون پاتے ہیں",
"""۱۔ اللہ کا ذکر دل کی سکون گاہ؛ ایمان والوں کے لیے راہنما۔
۲۔ ’’الَّذِينَ آمَنُوا وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ اللَّهِ أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ‘‘ — وہ لوگ جو ایمان لائے اور جن کے دل اللہ کے ذکر سے سکون پاتے ہیں — خبردار! اللہ کے ذکر سے ہی دل سکون پاتے ہیں — یعنی یہ وہ لوگ ہیں جو ایمان لائے اور جن کے دل اللہ کے ذکر سے سکون پاتے ہیں — خبردار! اللہ کے ذکر سے ہی دل سکون پاتے ہیں۔
۳۔ عملی سبق: روزانہ اللہ کا ذکر کریں؛ اعصابی تناؤ اور اضطراب کا اصل علاج اللہ سے قرب ہے۔"""
),
1736: (
"جو لوگ ایمان لائے اور نیک عمل کیے — ان کے لیے خوشخبری ہے اور بہترین انجام ہے",
"""۱۔ ایمان اور عملِ صالح — طُوبیٰ (جنت کی دولت) اور حسنِ مآب کا وعدہ۔
۲۔ ’’الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ طُوبَىٰ لَهُمْ وَحُسْنُ مَآبٍ‘‘ — جو لوگ ایمان لائے اور نیک عمل کیے — ان کے لیے خوشخبری ہے اور بہترین انجام ہے — یعنی جو لوگ ایمان لائے اور نیک عمل کیے — ان کے لیے طُوبیٰ ہے اور بہترین انجام ہے۔
۳۔ عملی سبق: ایمان کو عمل سے جوڑیں؛ یہی جنت کی کنجی ہے۔"""
),
1737: (
"یوں ہم نے آپ کو ایک ایسی قوم میں بھیجا جس سے پہلے قومیں گزر چکی ہیں — تاکہ آپ ان پر وہ وحی سنائیں جو ہم نے آپ کی طرف نازل کی ہے — اور وہ رحمن کا انکار کرتے ہیں — کہیے وہ میرا رب ہے — اس کے سوا کوئی معبود نہیں — اسی پر میں نے بھروسہ کیا اور اسی کی طرف میری توبہ ہے",
"""۱۔ ہر رسول ایک قوم کے لیے؛ قرآن کے مخالف رحمن کا انکار کرتے تھے؛ خالص توحیدِ نبی مثال۔
۲۔ ’’كَذَٰلِكَ أَرْسَلْنَاكَ فِي أُمَّۃٍ قَدْ خَلَتْ مِن قَبْلِهَا أُمَمٌ لِّتَتْلُوَ عَلَيْهِمُ الَّذِي أَوْحَيْنَا إِلَيْكَ وَهُمْ يَكْفُرُونَ بِالرَّحْمَٰنِ قُلْ هُوَ رَبِّي لَا إِلَٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ مَتَابِ‘‘ — یوں ہم نے آپ کو ایک ایسی قوم میں بھیجا جس سے پہلے قومیں گزر چکی ہیں — تاکہ آپ ان پر وہ وحی سنائیں جو ہم نے آپ کی طرف نازل کی ہے — اور وہ رحمن کا انکار کرتے ہیں — کہیے وہ میرا رب ہے — اس کے سوا کوئی معبود نہیں — اسی پر میں نے بھروسہ کیا اور اسی کی طرف میری توبہ ہے — یعنی اسی طرح ہم نے آپ کو ایک ایسی قوم میں بھیجا جس سے پہلے قومیں گزر چکی ہیں — تاکہ آپ ان پر وہ وحی سنائیں جو ہم نے آپ کی طرف نازل کی ہے — اور وہ رحمن کا انکار کرتے ہیں — کہیے وہ میرا رب ہے — اس کے سوا کوئی معبود نہیں — اسی پر میں نے بھروسہ کیا اور اسی کی طرف میری توبہ ہے۔
۳۔ عملی سبق: توحید پر استقامت — صرف اللہ پر بھروسہ — اور اسی کی طرف توبہ — ایمان کا ستون ہے۔"""
),
}
